import React, { createContext, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { ActivityIndicator, Appearance, BackHandler, DeviceEventEmitter, Dimensions, FlatList, Image, Modal, Platform, Pressable, SafeAreaView, ScrollView, StatusBar, StyleSheet, Switch, Text, TextInput, useColorScheme, View } from 'react-native';
