import * as IntentLauncher from 'expo-intent-launcher';
import NativeSlider from '@react-native-community/slider';
import { chooseSeriesCover, clearSeriesHistory, configureLibraryRoot, deleteSource, initializeLibrary, listChapters, listSeries, listSources, renameSource, saveSource, setSeriesCover, setSourceEnabled, StoredBook, StoredChapter, StoredSource, LibrarySeries, updateChapterProgress, updateReadingProgress } from './src/library';
