type Tab = 'library' | 'recent' | 'me';
type Screen = 'main' | 'sources' | 'document' | 'seriesDetail' | 'about';
type ThemeMode = 'light' | 'dark' | 'system';
type ThemeContextValue = { mode: ThemeMode; isDark: boolean; setMode: (mode: ThemeMode) => void };
const ThemeContext = createContext<ThemeContextValue>({ mode: 'system', isDark: false, setMode: () => undefined });
function useTheme() { return useContext(ThemeContext); }
let comicDarkTheme = true;
let comicRtlTheme = false;
function Slider(props: React.ComponentProps<typeof NativeSlider>) { return <NativeSlider {...props} inverted={comicRtlTheme} />; }

function IconButton({ name, onPress, dark = false }: { name: keyof typeof Ionicons.glyphMap; onPress?: () => void; dark?: boolean }) {
  const { isDark } = useTheme();
  return <Pressable onPress={onPress} style={styles.iconButton}><Ionicons name={name} size={22} color={dark || isDark ? '#F7F6FB' : '#28262D'} /></Pressable>;
}

function Progress({ value, color = '#7C5CFC' }: { value: number; color?: string }) {
  const { isDark } = useTheme();
  return <View style={[styles.progressTrack, isDark && styles.progressTrackDark]}><View style={[styles.progressFill, { width: `${value * 100}%`, backgroundColor: color }]} /></View>;
}

function SeriesProgress({ series, inverse = false }: { series: LibrarySeries; inverse?: boolean }) {
  const chapterPosition = series.currentChapterNumber ? Math.min(1, Math.max(0, series.currentChapterNumber / Math.max(1, series.chapterCount))) : 0;
  const chapterText = series.currentChapterId ? `章节 ${series.currentChapterNumber || 1} / ${series.chapterCount}` : '章节 0 / ' + series.chapterCount;
  return <View style={styles.seriesProgress}><Text numberOfLines={1} style={[styles.progressCaption, inverse && styles.progressCaptionInverse]}>{chapterText}</Text><Progress value={chapterPosition} color="#0F9F91" /><Text style={[styles.progressCaption, inverse && styles.progressCaptionInverse]}>本章 {Math.round(series.progress * 100)}%</Text><Progress value={series.progress} color="#A855F7" /></View>;
}

function SeriesLibrary({ series, importing, configureRoot, openSeries, continueSeries, openSources }: { series: LibrarySeries[]; importing: boolean; configureRoot: () => void; openSeries: (value: LibrarySeries) => void; continueSeries: (value: LibrarySeries) => void; openSources: () => void }) {
  const [query, setQuery] = useState(''); const [searching, setSearching] = useState(false);
  const { isDark } = useTheme();
  const visible = series.filter(item => `${item.title} ${item.author}`.toLowerCase().includes(query.trim().toLowerCase())); const featured = series.find(item => item.currentChapterId !== null);
  return <ScrollView contentContainerStyle={[styles.page, isDark && styles.pageDark]} showsVerticalScrollIndicator={false}>
    <View style={styles.header}><View><Text style={[styles.eyebrow, isDark && styles.textMutedDark]}>本地漫画库</Text><Text style={[styles.title, isDark && styles.textPrimaryDark]}>我的书架</Text></View><IconButton name={searching ? 'close' : 'search'} onPress={() => setSearching(!searching)} /></View>
    {searching && <View style={styles.search}><Ionicons name="search" size={18} color="#8A8691" /><TextInput value={query} onChangeText={setQuery} autoFocus placeholder="搜索作品名或章节" placeholderTextColor="#8A8691" style={styles.searchInput} /></View>}
    {featured && <Pressable style={styles.continueCard} onPress={() => continueSeries(featured)}>{featured.coverUri ? <Image source={{ uri: featured.coverUri }} style={styles.continueCover} /> : <View style={styles.continueFormat}><Text style={styles.formatText}>漫画</Text></View>}<View style={styles.continueBody}><View style={styles.pill}><Text style={styles.pillText}>继续阅读</Text></View><Text numberOfLines={1} style={styles.continueTitle}>{featured.title}</Text><SeriesProgress series={featured} inverse /></View></Pressable>}
    <View style={styles.sectionHeader}><Text style={[styles.sectionTitle, isDark && styles.textPrimaryDark]}>全部作品 · {series.length}</Text><Pressable onPress={openSources} style={styles.folderButton}><Ionicons name={importing ? 'sync' : 'folder-open'} size={18} color="#7257E7" /></Pressable></View>
    {series.length === 0 && <View style={[styles.emptyLibrary, isDark && styles.cardDark]}><View style={styles.emptyLibraryIcon}><Ionicons name="library-outline" size={38} color="#7257E7" /></View><Text style={[styles.emptyTitle, isDark && styles.textPrimaryDark]}>尚未设置漫画库</Text><Text style={[styles.emptyDescription, isDark && styles.textMutedDark]}>选择一个漫画源；其中每个一级子文件夹会作为一本作品，文件夹内的 EPUB、MOBI、PDF 会按章节整理。</Text><Pressable onPress={openSources} style={styles.primaryButton}><Text style={styles.primaryText}>添加漫画源</Text></Pressable></View>}
    <View style={styles.grid}>{visible.map(item => <Pressable key={item.id} onPress={() => openSeries(item)} style={styles.book}>{item.coverUri ? <Image source={{ uri: item.coverUri }} style={styles.cover} /> : <View style={styles.realCover}><Ionicons name="book" size={34} color="#fff" /><Text style={styles.formatText}>漫画</Text></View>}<Text numberOfLines={2} style={[styles.bookTitle, isDark && styles.textPrimaryDark]}>{item.title}</Text><SeriesProgress series={item} /></Pressable>)}</View>
  </ScrollView>;
}

function SeriesDetail({ series, chapters: seriesChapters, back, openChapter, continueReading, uploadCover }: { series: LibrarySeries; chapters: StoredChapter[]; back: () => void; openChapter: (chapter: StoredChapter) => void; continueReading: () => void; uploadCover: () => void }) {
  const chapterIndex = Math.max(0, seriesChapters.findIndex(item => item.id === series.currentChapterId)); const chapterProgress = series.currentChapterId ? (chapterIndex + 1) / Math.max(1, seriesChapters.length) : 0;
  const hasHistory = series.currentChapterId !== null;
  const { isDark } = useTheme();
  return <SafeAreaView style={[styles.safe, isDark && styles.safeDark]}><ScrollView contentContainerStyle={[styles.detailPage, isDark && styles.pageDark]}><View style={styles.detailTop}><IconButton name="chevron-back" onPress={back} /><IconButton name="image-outline" onPress={uploadCover} /></View><View style={styles.hero}>{series.coverUri ? <Image source={{ uri: series.coverUri }} style={styles.detailCover} /> : <View style={[styles.detailCover, styles.realCover]}><Ionicons name="book" size={38} color="#fff" /></View>}<View style={styles.heroBody}><Text style={[styles.detailTitle, isDark && styles.textPrimaryDark]}>{series.title}</Text><Text style={[styles.heroProgress, isDark && styles.textMutedDark]}>章节进度 {chapterIndex + 1} / {seriesChapters.length}</Text><Progress value={chapterProgress} color="#0F9F91" /><Text style={[styles.heroProgress, isDark && styles.textMutedDark]}>当前章节 {Math.round(series.progress * 100)}%</Text><Progress value={series.progress} color="#A855F7" /></View></View><Pressable style={styles.primaryButton} onPress={continueReading}><Ionicons name="book" size={20} color="#fff" /><Text style={styles.primaryText}>{hasHistory ? '继续阅读' : '开始阅读'}</Text></Pressable><View style={styles.sectionHeader}><Text style={[styles.sectionTitle, isDark && styles.textPrimaryDark]}>目录</Text><Text style={[styles.meta, isDark && styles.textMutedDark]}>共 {seriesChapters.length} 章</Text></View>{seriesChapters.map(chapter => <Pressable key={chapter.id} style={[styles.chapter, isDark && styles.chapterDark]} onPress={() => openChapter(chapter)}><View style={styles.chapterNumber}><Text style={styles.chapterNumberText}>{chapter.chapterNumber}</Text></View><View style={styles.flex}><Text numberOfLines={1} style={[styles.rowTitle, isDark && styles.textPrimaryDark]}>{chapter.chapterTitle}</Text><Text style={[styles.meta, isDark && styles.textMutedDark]}>{chapter.format.toUpperCase()} · {Math.round(chapter.progress * 100)}%</Text></View>{chapter.id === series.currentChapterId && <View style={styles.dot} />}</Pressable>)}</ScrollView></SafeAreaView>;
}

function Recent({ series, openSeries, clearHistory }: { series: LibrarySeries[]; openSeries: (value: LibrarySeries) => void; clearHistory: (id: number) => void }) {
  const readSeries = series.filter(item => item.currentChapterId !== null);
  const { isDark } = useTheme();
  return <ScrollView contentContainerStyle={[styles.page, isDark && styles.pageDark]}><Text style={[styles.title, isDark && styles.textPrimaryDark]}>最近阅读</Text><Text style={[styles.subheading, isDark && styles.textMutedDark]}>按作品记录你的真实阅读进度</Text>{readSeries.length === 0 && <View style={styles.empty}><Ionicons name="time-outline" size={36} color="#B2ADB7" /><Text style={[styles.meta, isDark && styles.textMutedDark]}>开始阅读一个章节后，它会出现在这里</Text></View>}{readSeries.map(item => <View key={item.id} style={styles.historyRow}>{item.coverUri ? <Image source={{ uri: item.coverUri }} style={styles.historyCover} /> : <View style={styles.historyFormat}><Text style={styles.formatText}>漫画</Text></View>}<Pressable style={styles.flex} onPress={() => openSeries(item)}><Text style={[styles.rowTitle, isDark && styles.textPrimaryDark]}>{item.title}</Text><Text style={[styles.meta, isDark && styles.textMutedDark]}>阅读至 {item.currentChapterTitle || '章节'} · {Math.round(item.progress * 100)}%</Text></Pressable><Pressable onPress={() => clearHistory(item.id)} style={styles.historyDelete}><Ionicons name="trash-outline" size={20} color={isDark ? '#B8B1C2' : '#9A949F'} /></Pressable></View>)}</ScrollView>;
}

function Me({ navigate }: { navigate: (screen: Screen) => void }) {
  const groups = [[['folder-open-outline', '漫画源']], [['information-circle-outline', '关于 Veader']]];
  const destinations: Record<string, Screen> = { '漫画源': 'sources', '关于 Veader': 'about' };
  const { mode, isDark, setMode } = useTheme(); const [themeOpen, setThemeOpen] = useState(false);
  const modeLabel = mode === 'system' ? '随系统自动' : mode === 'dark' ? '黑夜' : '白天';
  return <View style={[styles.flex, isDark && styles.pageDark]}><ScrollView contentContainerStyle={[styles.page, isDark && styles.pageDark]}><View style={styles.header}><Text style={[styles.title, isDark && styles.textPrimaryDark]}>我的</Text><Pressable style={styles.themeButton} onPress={() => setThemeOpen(true)}><Ionicons name={isDark ? 'moon' : 'sunny'} size={20} color={isDark ? '#E9D5FF' : '#7257E7'} /><Text style={[styles.themeButtonText, isDark && styles.textPrimaryDark]}>{modeLabel}</Text></Pressable></View><View style={styles.profile}><View style={styles.avatar}><Ionicons name="person" size={30} color="#fff" /></View><View><Text style={[styles.rowTitle, isDark && styles.textPrimaryDark]}>本地读者</Text><Text style={[styles.meta, isDark && styles.textMutedDark]}>数据仅保存在当前设备</Text></View></View>{groups.map((g, gi) => <View style={[styles.settingsGroup, isDark && styles.cardDark]} key={gi}>{g.map(([icon, label], i) => <Pressable onPress={() => navigate(destinations[label!]!)} style={[styles.settingRow, i < g.length - 1 && styles.divider, isDark && styles.dividerDark]} key={label}><View style={styles.settingIcon}><Ionicons name={icon as any} size={20} color="#7257E7" /></View><Text style={[styles.settingLabel, isDark && styles.textPrimaryDark]}>{label}</Text><Ionicons name="chevron-forward" size={18} color={isDark ? '#B8B1C2' : '#AAA5B0'} /></Pressable>)}</View>)}</ScrollView><Modal visible={themeOpen} transparent animationType="slide" onRequestClose={() => setThemeOpen(false)}><Pressable style={styles.modalShade} onPress={() => setThemeOpen(false)} /><View style={[styles.sheet, isDark && styles.sheetDark]}><View style={styles.sheetHandle} /><Text style={[styles.sheetTitle, isDark && styles.textPrimaryDark]}>界面主题</Text>{([['light', '白天', 'sunny-outline'], ['dark', '黑夜', 'moon-outline'], ['system', '随系统自动', 'contrast-outline']] as [ThemeMode, string, keyof typeof Ionicons.glyphMap][]).map(([value, label, icon]) => <Pressable key={value} onPress={() => { setMode(value); setThemeOpen(false); }} style={[styles.themeOption, mode === value && styles.themeOptionActive, isDark && mode !== value && styles.themeOptionDark]}><Ionicons name={icon} size={21} color={mode === value ? '#7257E7' : isDark ? '#DDD5E8' : '#6D6674'} /><Text style={[styles.themeOptionText, mode === value && styles.themeOptionTextActive, isDark && mode !== value && styles.textPrimaryDark]}>{label}</Text>{mode === value && <Ionicons name="checkmark-circle" size={21} color="#7257E7" />}</Pressable>)}</View></Modal></View>;
}

function SettingsPage({ screen, back }: { screen: Screen; back: () => void }) {
  const titles: Partial<Record<Screen, string>> = { about: '关于 Veader' };
  const { isDark } = useTheme();
  return <SafeAreaView style={[styles.safe, isDark && styles.safeDark]}><ScrollView contentContainerStyle={[styles.page, isDark && styles.pageDark]}><View style={styles.header}><IconButton name="chevron-back" onPress={back} /><Text style={[styles.navTitle, isDark && styles.textPrimaryDark]}>{titles[screen]}</Text><View style={{ width: 42 }} /></View>
    <View style={[styles.aboutCard, isDark && styles.cardDark]}><View style={styles.aboutLogo}><Ionicons name="book" size={38} color="#fff" /></View><Text style={[styles.detailTitle, isDark && styles.textPrimaryDark]}>Veader</Text><Text style={[styles.meta, isDark && styles.textMutedDark]}>版本 0.1.0 · Android 测试版</Text><Text style={[styles.modalHelp, isDark && styles.textMutedDark]}>本地优先的漫画与电子书阅读器。支持 EPUB、MOBI、PDF 导入及本机阅读记录。</Text></View>
  </ScrollView></SafeAreaView>;
}

type SourceKind = '本地文件夹' | 'SMB' | 'FTP';

function Sources({ back, onBooksChanged }: { back: () => void; onBooksChanged: () => void }) {
  const [showAdd, setShowAdd] = useState(false); const [loading, setLoading] = useState(false);
  const [kind, setKind] = useState<SourceKind>('本地文件夹'); const [sources, setSources] = useState<StoredSource[]>([]);
  const [name, setName] = useState(''); const [address, setAddress] = useState('');
  const [editing, setEditing] = useState<StoredSource | null>(null); const [editName, setEditName] = useState(''); const [swipedId, setSwipedId] = useState<number | null>(null); const touchStart = useRef(0);
  const { isDark } = useTheme();
  const refresh = () => listSources().then(setSources).catch(console.warn);
  useEffect(() => { refresh(); }, []);
  const chooseLocalFolder = async () => { setShowAdd(false); setLoading(true); try { await configureLibraryRoot(); await refresh(); onBooksChanged(); } catch (reason) { console.warn('漫画总文件夹扫描失败', reason); } finally { setLoading(false); } };
  const add = async () => {
    if (kind === '本地文件夹') return chooseLocalFolder();
    if (!name.trim() || !address.trim()) return;
    await saveSource(kind.toLowerCase() as 'smb' | 'ftp', name.trim(), address.trim()); await refresh(); setName(''); setAddress(''); setShowAdd(false);
  };
  const toggle = async (source: StoredSource, enabled: boolean) => { await setSourceEnabled(source.id, enabled); refresh(); };
  const remove = async (source: StoredSource) => { await deleteSource(source.id); setSwipedId(null); await refresh(); onBooksChanged(); };
  const startRename = (source: StoredSource) => { setEditName(source.name); setEditing(source); };
  const commitRename = async () => { if (!editing || !editName.trim()) return; await renameSource(editing.id, editName); setEditing(null); refresh(); };
  return <SafeAreaView style={[styles.safe, isDark && styles.safeDark]}><ScrollView contentContainerStyle={[styles.page, isDark && styles.pageDark]}>
    <View style={styles.header}><IconButton name="chevron-back" onPress={back} /><Text style={[styles.navTitle, isDark && styles.textPrimaryDark]}>漫画源</Text><IconButton name="add" onPress={() => setShowAdd(true)} /></View>
    <View style={[styles.scanCard, isDark && styles.scanCardDark]}><View style={styles.scanIcon}><Ionicons name="library" size={22} color="#7257E7" /></View><View style={styles.flex}><Text style={[styles.rowTitle, isDark && styles.textPrimaryDark]}>漫画统计</Text><Text style={[styles.meta, isDark && styles.textMutedDark]}>{sources.length} 个漫画源 · {sources.reduce((sum, source) => sum + source.bookCount, 0)} 部已扫描作品</Text></View>{loading && <ActivityIndicator color="#7257E7" />}</View>
    <Text style={styles.settingSection}>已添加 · {sources.length}</Text>
    {sources.length === 0 && <View style={styles.empty}><Ionicons name="folder-open-outline" size={36} color="#B2ADB7" /><Text style={styles.meta}>尚未添加任何漫画源</Text></View>}
    {sources.map(source => <View key={source.id} style={styles.sourceSwipe}><Pressable style={styles.sourceDelete} onPress={() => remove(source)}><Ionicons name="trash-outline" size={21} color="#fff" /><Text style={styles.sourceDeleteText}>删除</Text></Pressable><Pressable onLongPress={() => startRename(source)} onTouchStart={event => { touchStart.current = event.nativeEvent.pageX; }} onTouchEnd={event => { if (touchStart.current - event.nativeEvent.pageX > 45) setSwipedId(source.id); else if (event.nativeEvent.pageX - touchStart.current > 25) setSwipedId(null); }} style={[styles.sourceCard, isDark && styles.cardDark, swipedId === source.id && styles.sourceCardShift]}><View style={[styles.sourceIcon, { backgroundColor: source.type === 'local' ? '#7257E7' : '#4D9E81' }]}><Ionicons name={source.type === 'local' ? 'folder' : 'server'} size={23} color="#fff" /></View><View style={styles.flex}><Text style={[styles.rowTitle, isDark && styles.textPrimaryDark]}>{source.name}</Text><Text numberOfLines={1} style={[styles.meta, isDark && styles.textMutedDark]}>{source.type.toUpperCase()} · {source.endpoint}</Text><Text style={styles.sourceStatus}>{source.type === 'local' ? `${source.bookCount} 部作品 · 长按重命名` : '已保存配置 · 协议连接待启用'}</Text></View><Switch value={source.enabled} onValueChange={enabled => toggle(source, enabled)} trackColor={{ true: '#765BE8' }} /></Pressable></View>)}
    <Pressable style={styles.dashedButton} onPress={() => setShowAdd(true)}><Ionicons name="add-circle-outline" size={21} color="#7257E7" /><Text style={styles.dashedText}>添加漫画源</Text></Pressable>
  </ScrollView><Modal visible={showAdd} transparent animationType="slide" onRequestClose={() => setShowAdd(false)}><Pressable style={styles.modalShade} onPress={() => setShowAdd(false)} /><View style={styles.sheet}><View style={styles.sheetHandle} /><Text style={styles.sheetTitle}>添加漫画源</Text><Text style={styles.settingSection}>来源类型</Text><View style={styles.segment}>{(['本地文件夹', 'SMB', 'FTP'] as SourceKind[]).map(v => <Pressable key={v} onPress={() => setKind(v)} style={[styles.segmentItem, kind === v && styles.segmentActive]}><Text style={[styles.segmentText, kind === v && styles.segmentTextActive]}>{v}</Text></Pressable>)}</View>{kind === '本地文件夹' ? <><Text style={styles.modalHelp}>将打开 Android 系统目录选择器。授权后会扫描其中的 EPUB、MOBI 和 PDF。</Text><Pressable style={styles.primaryButton} onPress={chooseLocalFolder}><Ionicons name="folder-open" size={20} color="#fff" /><Text style={styles.primaryText}>选择系统文件夹</Text></Pressable></> : <><TextInput value={name} onChangeText={setName} placeholder="显示名称" placeholderTextColor="#99939E" style={styles.input} /><TextInput value={address} onChangeText={setAddress} placeholder={kind === 'SMB' ? 'smb://服务器/共享目录' : 'ftp://服务器/目录'} placeholderTextColor="#99939E" autoCapitalize="none" style={styles.input} /><Text style={styles.modalHelp}>当前保存真实配置，但 SMB/FTP 原生连接器尚未启用，不会伪造扫描结果。</Text><Pressable style={[styles.primaryButton, (!name.trim() || !address.trim()) && { opacity: .45 }]} onPress={add}><Text style={styles.primaryText}>保存配置</Text></Pressable></>}</View></Modal><Modal visible={editing !== null} transparent animationType="fade" onRequestClose={() => setEditing(null)}><Pressable style={styles.modalShade} onPress={() => setEditing(null)} /><View style={styles.sheet}><View style={styles.sheetHandle} /><Text style={styles.sheetTitle}>重命名漫画源</Text><TextInput value={editName} onChangeText={setEditName} autoFocus placeholder="漫画源名称" placeholderTextColor="#99939E" style={styles.input} /><Pressable style={[styles.primaryButton, !editName.trim() && { opacity: .45 }]} onPress={commitRename}><Text style={styles.primaryText}>保存名称</Text></Pressable></View></Modal></SafeAreaView>;
}

function OptionSet({ values, value, onChange }: { values: string[]; value: string; onChange: (value: string) => void }) {
  return <View style={styles.segment}>{values.map(v => <Pressable key={v} onPress={() => onChange(v)} style={[styles.segmentItem, value === v && styles.segmentActive]}><Text style={[styles.segmentText, value === v && styles.segmentTextActive]}>{v}</Text></Pressable>)}</View>;
}

function EpubPageView({ book, page, width, height, crop = false, dark = comicDarkTheme }: { book: StoredBook; page: EpubComicPage; width: number; height: number; crop?: boolean; dark?: boolean }) {
  const [source, setSource] = useState<string>(); const [error, setError] = useState(false);
  useEffect(() => { let active = true; loadEpubPage(book, page).then(uri => active && setSource(uri)).catch(() => active && setError(true)); return () => { active = false; }; }, [book, page]);
  return <View style={[styles.epubPage, { width, height, backgroundColor: dark ? '#09090B' : '#FFFFFF' }]}>{source ? <Image source={{ uri: source }} style={styles.epubImage} resizeMode={crop ? 'cover' : 'contain'} /> : <View style={styles.readerMessage}>{error ? <><Ionicons name="warning-outline" size={32} color="#E1915F" /><Text style={styles.readerChapter}>第 {page.index + 1} 页加载失败</Text></> : <ActivityIndicator color="#8B70F7" />}</View>}</View>;
}

function ComicEpubReader({ book, back, onProgress, onSetCover }: { book: StoredBook; back: () => void; onProgress?: (progress: number, location: string) => void; onSetCover?: (uri: string) => void }) {
  const [comic, setComic] = useState<EpubComic>(); const [error, setError] = useState(''); const [menu, setMenu] = useState(true); const [directory, setDirectory] = useState(false); const [settings, setSettings] = useState(false);
  const [readingDirection, setReadingDirection] = useState<'ltr' | 'rtl'>('ltr'); const [tapZones, setTapZones] = useState(true); const [reverseTap, setReverseTap] = useState(false); const [smooth, setSmooth] = useState(true); const [dark, setDark] = useState(true); const [crop, setCrop] = useState(false); const [notch, setNotch] = useState(false); const [volume, setVolume] = useState(true);
  const [currentPage, setCurrentPage] = useState(0); const { width, height } = Dimensions.get('window'); const listRef = useRef<FlatList<EpubComicPage>>(null); const touchStart = useRef({ x: 0, y: 0, time: 0 });
  useEffect(() => { loadEpubComic(book).then(value => { const restoredPage = Math.max(0, Math.round(book.progress * (value.pages.length - 1))); setComic(value); setReadingDirection(value.direction); setCurrentPage(restoredPage); (onProgress ?? ((progress, location) => updateReadingProgress(book.id, progress, location).catch(console.warn)))(restoredPage / Math.max(1, value.pages.length - 1), `epub:${restoredPage}`); }).catch(reason => setError(reason instanceof Error ? reason.message : String(reason))); }, [book]);
  const pageChanged = (page: number) => { if (!comic) return; const safe = Math.max(0, Math.min(comic.pages.length - 1, page)); setCurrentPage(safe); (onProgress ?? ((progress, location) => updateReadingProgress(book.id, progress, location).catch(console.warn)))(safe / Math.max(1, comic.pages.length - 1), `epub:${safe}`); };
  const displayPages = useMemo(() => !comic ? [] : readingDirection === 'rtl' ? [...comic.pages].reverse() : comic.pages, [comic, readingDirection]);
  const toDisplay = (actual: number) => readingDirection === 'rtl' && comic ? comic.pages.length - 1 - actual : actual;
  const toActual = (display: number) => readingDirection === 'rtl' && comic ? comic.pages.length - 1 - display : display;
  const goTo = (actual: number, animated = smooth) => { if (!comic) return; const safe = Math.max(0, Math.min(comic.pages.length - 1, actual)); listRef.current?.scrollToIndex({ index: toDisplay(safe), animated }); pageChanged(safe); };
  const handleTap = (x: number) => { if (!comic) return; if (!tapZones) return setMenu(!menu); if (x >= width / 3 && x <= width * 2 / 3) return setMenu(!menu); const naturalNext = readingDirection === 'rtl' ? x < width / 3 : x > width * 2 / 3; const next = reverseTap ? !naturalNext : naturalNext; goTo(currentPage + (next ? 1 : -1)); };
  const changeDirection = (value: string) => { const direction = value === '从右到左' ? 'rtl' : 'ltr'; comicRtlTheme = direction === 'rtl'; setReadingDirection(direction); setTimeout(() => listRef.current?.scrollToIndex({ index: direction === 'rtl' && comic ? comic.pages.length - 1 - currentPage : currentPage, animated: false }), 0); };
  useEffect(() => { const subscription = DeviceEventEmitter.addListener('veaderVolumeKey', (key: string) => { if (!volume) return; goTo(currentPage + (key === 'up' ? -1 : 1)); }); return () => subscription.remove(); }, [volume, currentPage, comic, smooth]);
  comicRtlTheme = readingDirection === 'rtl'; comicDarkTheme = dark;
  if (error) return <SafeAreaView style={styles.documentReader}><View style={styles.documentTop}><IconButton name="chevron-back" onPress={back} dark /><Text style={styles.readerBook}>{book.title}</Text></View><View style={styles.readerMessage}><Ionicons name="warning-outline" size={38} color="#E1915F" /><Text style={styles.errorText}>{error}</Text></View></SafeAreaView>;
  if (!comic) return <SafeAreaView style={styles.documentReader}><View style={styles.readerMessage}><ActivityIndicator color="#8B70F7" size="large" /><Text style={styles.readerChapter}>正在建立 EPUB 页表…</Text></View></SafeAreaView>;
  return <View style={[styles.comicReader, { backgroundColor: dark ? '#09090B' : '#E9E5DE' }]}><StatusBar hidden={!menu} barStyle="light-content" /><FlatList ref={listRef} data={displayPages} horizontal pagingEnabled initialScrollIndex={toDisplay(currentPage)} getItemLayout={(_, index) => ({ length: width, offset: width * index, index })} windowSize={3} initialNumToRender={2} maxToRenderPerBatch={2} removeClippedSubviews keyExtractor={page => page.imageUri} showsHorizontalScrollIndicator={false} renderItem={({ item }) => <EpubPageView book={book} page={item} width={width} height={height} />} onTouchStart={event => { touchStart.current = { x: event.nativeEvent.pageX, y: event.nativeEvent.pageY, time: Date.now() }; }} onTouchEnd={event => { const start = touchStart.current; if (Date.now() - start.time < 350 && Math.abs(event.nativeEvent.pageX - start.x) < 12 && Math.abs(event.nativeEvent.pageY - start.y) < 12) handleTap(event.nativeEvent.pageX); }} onMomentumScrollEnd={event => pageChanged(toActual(Math.round(event.nativeEvent.contentOffset.x / width)))} />{menu && <><View style={[styles.readerTop, styles.readerOverlay]}><IconButton name="chevron-back" onPress={back} dark /><View style={styles.readerTopTitle}><Text numberOfLines={1} style={styles.readerBook}>{comic.title}</Text><Text style={styles.readerChapter}>{comic.author} · {readingDirection === 'rtl' ? '从右到左' : '从左到右'}</Text></View><IconButton name="options" onPress={() => setSettings(true)} dark /></View><View style={[styles.epubBottom, styles.readerOverlay]}><Text numberOfLines={1} style={styles.chapterLabel}>{comic.title} · 整卷</Text><Slider style={styles.readerSlider} minimumValue={0} maximumValue={comic.pages.length - 1} step={1} value={currentPage} minimumTrackTintColor="#8B70F7" maximumTrackTintColor="#55515B" thumbTintColor="#FFFFFF" onSlidingComplete={value => goTo(value)} /><Text style={styles.epubCounter}>第 {currentPage + 1} / {comic.pages.length} 页</Text><View style={styles.quickActions}><Pressable style={styles.quickAction} onPress={back}><Ionicons name="list-outline" size={21} color="#fff" /><Text style={styles.actionText}>章节目录</Text></Pressable><Pressable style={styles.quickAction} onPress={() => setSettings(true)}><Ionicons name="options-outline" size={21} color="#fff" /><Text style={styles.actionText}>详细设置</Text></Pressable></View></View></>}
    <Modal visible={directory} transparent animationType="slide" onRequestClose={() => setDirectory(false)}><Pressable style={styles.modalShade} onPress={() => setDirectory(false)} /><View style={[styles.sheet, styles.tallSheet]}><View style={styles.sheetHandle} /><View style={styles.sheetHeading}><Text style={styles.sheetTitle}>页面目录</Text><Text style={styles.done} onPress={() => setDirectory(false)}>完成</Text></View><Text style={styles.meta}>共 {comic.pages.length} 页，当前第 {currentPage + 1} 页</Text><ScrollView contentContainerStyle={styles.pageGrid}>{comic.pages.map((_, index) => <Pressable key={index} onPress={() => { goTo(index, false); setDirectory(false); }} style={[styles.pageChip, currentPage === index && styles.pageChipActive]}><Text style={[styles.pageChipText, currentPage === index && { color: '#fff' }]}>{index + 1}</Text></Pressable>)}</ScrollView></View></Modal>
    <Modal visible={settings} transparent animationType="slide" onRequestClose={() => setSettings(false)}><Pressable style={styles.modalShade} onPress={() => setSettings(false)} /><View style={[styles.sheet, styles.tallSheet]}><View style={styles.sheetHandle} /><ScrollView><View style={styles.sheetHeading}><Text style={styles.sheetTitle}>详细阅读设置</Text><Text style={styles.done} onPress={() => setSettings(false)}>完成</Text></View>{onSetCover && <Pressable style={styles.coverAction} onPress={() => { onSetCover(comic.pages[currentPage]!.imageUri); setSettings(false); }}><Ionicons name="image-outline" size={20} color="#7257E7" /><Text style={styles.coverActionText}>将当前第 {currentPage + 1} 页设为作品封面</Text></Pressable>}<Text style={styles.settingSection}>阅读方向</Text><OptionSet values={['从左到右', '从右到左']} value={readingDirection === 'rtl' ? '从右到左' : '从左到右'} onChange={changeDirection} /><Text style={styles.settingSection}>翻页效果</Text><OptionSet values={['直接翻页', '平滑翻页']} value={smooth ? '平滑翻页' : '直接翻页'} onChange={value => setSmooth(value === '平滑翻页')} /><View style={styles.toggleRow}><Text style={styles.toggleText}>点击区域翻页</Text><Switch value={tapZones} onValueChange={setTapZones} trackColor={{ true: '#765BE8' }} /></View><View style={styles.toggleRow}><View style={styles.flex}><Text style={styles.toggleText}>反转点击区域</Text><Text style={styles.meta}>{reverseTap ? '翻页区域与阅读方向相反' : '翻页区域跟随阅读方向'}</Text></View><Switch value={reverseTap} onValueChange={setReverseTap} disabled={!tapZones} trackColor={{ true: '#765BE8' }} /></View><View style={styles.toggleRow}><Text style={styles.toggleText}>黑色阅读背景</Text><Switch value={dark} onValueChange={setDark} trackColor={{ true: '#765BE8' }} /></View><View style={styles.tapPreview}><View style={styles.tapPreviewSide}><Text style={styles.tapPreviewText}>{readingDirection === 'rtl' !== reverseTap ? '下一页' : '上一页'}</Text></View><View style={styles.tapPreviewCenter}><Text style={styles.tapPreviewText}>菜单</Text></View><View style={styles.tapPreviewSide}><Text style={styles.tapPreviewText}>{readingDirection === 'rtl' !== reverseTap ? '上一页' : '下一页'}</Text></View></View></ScrollView></View></Modal>
  </View>;
}

function DocumentReader({ book, back, onProgress, onSetCover }: { book: StoredBook; back: () => void; onProgress?: (progress: number, location: string) => void; onSetCover?: (uri: string) => void }) {
  if (book.format === 'epub') return <ComicEpubReader book={book} back={back} onProgress={onProgress} onSetCover={onSetCover} />;
  const [content, setContent] = useState<RenderableContent>(); const [error, setError] = useState('');
  useEffect(() => { loadRenderableContent(book).then(setContent).catch(reason => setError(reason instanceof Error ? reason.message : String(reason))); }, [book]);
  const openPdf = async () => {
    try {
      if (Platform.OS === 'android') {
        const contentUri = await FileSystem.getContentUriAsync(book.localUri);
        await IntentLauncher.startActivityAsync('android.intent.action.VIEW', { data: contentUri, type: 'application/pdf', flags: 1 });
      }
    } catch (reason) { setError(reason instanceof Error ? reason.message : String(reason)); }
  };
  return <SafeAreaView style={styles.documentReader}><View style={styles.documentTop}><IconButton name="chevron-back" onPress={back} dark /><View style={styles.flex}><Text numberOfLines={1} style={styles.readerBook}>{book.title}</Text><Text style={styles.readerChapter}>{book.format.toUpperCase()} · {book.author || '未知作者'}</Text></View><IconButton name="options" dark /></View>{error ? <View style={styles.readerMessage}><Ionicons name="warning-outline" size={34} color="#E1915F" /><Text style={styles.errorText}>{error}</Text></View> : !content ? <View style={styles.readerMessage}><ActivityIndicator color="#7257E7" size="large" /><Text style={styles.readerChapter}>正在解析 {book.format.toUpperCase()}…</Text></View> : content.kind === 'html' ? <WebView originWhitelist={['*']} source={{ html: content.html }} style={styles.webReader} javaScriptEnabled={false} allowFileAccess /> : Platform.OS === 'ios' ? <WebView source={{ uri: content.uri }} style={styles.webReader} allowFileAccess /> : <View style={styles.readerMessage}><View style={styles.pdfIcon}><Ionicons name="document-text" size={42} color="#fff" /></View><Text style={styles.pdfTitle}>{book.title}</Text><Text style={styles.pdfHint}>Android 将使用已安装的 PDF 查看器打开此文件，阅读文件仍保存在 Veader 沙盒中。</Text><Pressable style={styles.primaryButton} onPress={openPdf}><Ionicons name="open-outline" size={20} color="#fff" /><Text style={styles.primaryText}>打开 PDF</Text></Pressable></View>}</SafeAreaView>;
}

function AppContent() {
  const { isDark } = useTheme();
  const [tab, setTab] = useState<Tab>('library'); const [screen, setScreen] = useState<Screen>('main');
  const [selectedStored, setSelectedStored] = useState<StoredBook>(); const [importing, setImporting] = useState(false);
  const [series, setSeries] = useState<LibrarySeries[]>([]); const [selectedSeries, setSelectedSeries] = useState<LibrarySeries>(); const [seriesChapters, setSeriesChapters] = useState<StoredChapter[]>([]);
  const refreshBooks = async () => { setSeries(await listSeries()); };
  useEffect(() => { initializeLibrary().then(refreshBooks).catch(console.warn); }, []);
  const goBack = () => { if (screen === 'document') refreshBooks().catch(console.warn); setScreen(screen === 'document' ? 'seriesDetail' : 'main'); };
  useEffect(() => { const subscription = BackHandler.addEventListener('hardwareBackPress', () => { if (screen === 'main') return false; goBack(); return true; }); return () => subscription.remove(); }, [screen]);
  const configureRoot = async () => { setImporting(true); try { await configureLibraryRoot(); await refreshBooks(); } finally { setImporting(false); } };
  const openSeries = async (value: LibrarySeries) => { setSelectedSeries(value); setSeriesChapters(await listChapters(value.id)); setScreen('seriesDetail'); };
  const openChapter = (chapter: StoredChapter) => { setSelectedStored(chapter); setScreen('document'); };
  const continueSeries = async (value: LibrarySeries) => { const chapters = await listChapters(value.id); const target = chapters.find(chapter => chapter.id === value.currentChapterId) || chapters[0]; if (target) { setSelectedSeries(value); setSeriesChapters(chapters); openChapter(target); } };
  const content = useMemo(() => tab === 'library' ? <SeriesLibrary series={series} importing={importing} configureRoot={configureRoot} openSeries={openSeries} continueSeries={continueSeries} openSources={() => setScreen('sources')} /> : tab === 'recent' ? <Recent series={series} openSeries={openSeries} clearHistory={id => clearSeriesHistory(id).then(refreshBooks).catch(console.warn)} /> : <Me navigate={setScreen} />, [tab, series, importing]);
  if (screen === 'document' && selectedStored) return <DocumentReader book={selectedStored} back={goBack} onProgress={(progress, location) => { if ('seriesId' in selectedStored) updateChapterProgress(selectedStored as StoredChapter, progress, location).catch(console.warn); }} onSetCover={uri => { if (selectedSeries) setSeriesCover(selectedSeries.id, uri).then(refreshBooks).catch(console.warn); }} />;
  if (screen === 'seriesDetail' && selectedSeries) return <SeriesDetail series={selectedSeries} chapters={seriesChapters} back={() => setScreen('main')} openChapter={openChapter} continueReading={() => continueSeries(selectedSeries)} uploadCover={() => chooseSeriesCover(selectedSeries.id).then(async () => { await refreshBooks(); const updated = (await listSeries()).find(item => item.id === selectedSeries.id); if (updated) setSelectedSeries(updated); }).catch(console.warn)} />;
  if (screen === 'sources') return <Sources back={goBack} onBooksChanged={() => refreshBooks().catch(console.warn)} />;
  if (screen === 'about') return <SettingsPage screen={screen} back={goBack} />;
  const tabs: { key: Tab; label: string; icon: keyof typeof Ionicons.glyphMap }[] = [{ key: 'library', label: '首页', icon: 'library' }, { key: 'recent', label: '最近', icon: 'time' }, { key: 'me', label: '我的', icon: 'person' }];
  return <SafeAreaView style={[styles.safe, isDark && styles.safeDark]}><StatusBar barStyle={isDark ? 'light-content' : 'dark-content'} backgroundColor={isDark ? '#111114' : '#F8F7FA'} /><View style={styles.flex}>{content}</View><View style={[styles.tabBar, isDark && styles.tabBarDark]}>{tabs.map(t => <Pressable key={t.key} style={styles.tab} onPress={() => setTab(t.key)}><View style={tab === t.key ? styles.tabActive : undefined}><Ionicons name={tab === t.key ? t.icon : `${t.icon}-outline` as any} size={22} color={tab === t.key ? '#A855F7' : isDark ? '#B8B1C2' : '#8E8994'} /></View><Text style={[styles.tabText, tab === t.key && styles.tabTextActive, isDark && styles.tabTextDark]}>{t.label}</Text></Pressable>)}</View></SafeAreaView>;
}

export default function App() {
  const systemScheme = useColorScheme();
  const [mode, setMode] = useState<ThemeMode>('system');
  const isDark = mode === 'dark' || (mode === 'system' && systemScheme === 'dark');
  const theme = useMemo(() => ({ mode, isDark, setMode }), [mode, isDark]);
  return <ThemeContext.Provider value={theme}><AppContent /></ThemeContext.Provider>;
}

